"""一次性独立复核 v67 捕获、轨迹与离线见证，不执行任何求解。"""
import argparse, ast, copy, datetime, gzip, hashlib, json, math, re, struct, sys, zipfile
from array import array
from decimal import Decimal, localcontext
from fractions import Fraction
from pathlib import Path
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "knowledge/experiments/data/2026-10-12-halpern-ipm"
WORK = ROOT / ".tools/v67-diagnostic"
PLAN_SHA = "0dafab3cc269cec22abe22bb2dbff014dd7a8d2d45255acd54ac3bfad0f42c8b"
ANALYZER_SHA = "e79200011b53a3d982681365b5134a546223515837e0ece870de4cb860e14322"
ANALYSIS_SHA = "6b709f26d36184003b8fcb2db80cdf7e83f4d2307c7592bed90165982658cb3f"
VARIANTS = ("frozen_v66", "diagnostic_off", "diagnostic_on")
ZERO = Fraction(0)
CHECKS = 0
COUNT_FIELDS = ('ipm_iterations', 'ipm_factorizations', 'ipm_refinement_steps', 'ipm_weighted_krylov_steps', 'ipm_krylov_recycle_projections', 'ipm_krylov_recycle_acceptances', 'ipm_krylov_recycle_vectors', 'ipm_krylov_recycle_peak_dimension', 'ipm_regularization_searches', 'ipm_regularization_reductions', 'ipm_unshifted_factorizations', 'ipm_full_newton_preconditioner_solves', 'ipm_full_newton_products', 'ipm_bounded_newton_returns', 'ipm_bounded_newton_inexact_returns', 'ipm_homogeneous_constant_solves', 'ipm_homogeneous_constant_repairs', 'ipm_homogeneous_constant_repair_successes', 'ipm_homogeneous_direction_solves', 'ipm_homogeneous_scaled_products', 'ipm_homogeneous_scaled_refinement_steps', 'ipm_homogeneous_scaled_inexact_returns', 'ipm_direction_retries', 'ipm_direction_retry_successes', 'ipm_schur_residual_products', 'ipm_schur_refinement_steps', 'ipm_schur_refinement_acceptances', 'ipm_kkt_dimension', 'ipm_factor_nonzeros', 'ipm_structural_fallbacks', 'ipm_eliminated_singletons', 'ipm_regularized_pivots', 'ipm_backward_error_acceptances', 'ipm_inexact_acceptances', 'ipm_inexact_prefilter_rejections', 'ipm_eliminated_fixed_variables', 'ipm_presolved_singleton_rows', 'ipm_presolved_fixed_columns', 'ipm_central_correction_attempts', 'ipm_central_correction_acceptances')

def require(condition, message):
    global CHECKS
    CHECKS += 1
    if not condition:
        raise AssertionError(message)

def strict(text):
    def pairs(values):
        result = {}
        for key, value in values:
            require(key not in result, "JSON 重复键")
            result[key] = value
        return result
    def number(text):
        value = float(text)
        require(math.isfinite(value), "JSON 非有限浮点")
        return value
    def invalid(text):
        raise ValueError("JSON 非有限常量：" + text)
    return json.loads(text, object_pairs_hook=pairs, parse_float=number, parse_constant=invalid)

def read(path):
    return strict(Path(path).read_text(encoding="utf-8"))

def sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def finite(value):
    return type(value) in (int, float) and math.isfinite(value)

def same(a, b):
    if type(a) is bool or type(b) is bool:
        return type(a) is type(b) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[key], b[key]) for key in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def flags(arguments):
    require(len(arguments) % 2 == 0, "参数必须成对")
    result = dict(zip(arguments[::2], arguments[1::2]))
    require(len(result) * 2 == len(arguments) and all(key.startswith("--") for key in result), "重复或非法参数")
    return result


def integer(value):
    return type(value) is int and 0 <= value < (1 << 63)


def valid_report(row):
    r = row.get("report")
    if row.get("error") is not None or not isinstance(r,dict) or type(row.get("returncode")) is not int:
        return False
    if r.get("backend") != "ipm" or r.get("backend_version") != "ipm-cpu-0.53.0" or type(r.get("schema_version")) is not int or r["schema_version"] != 1:
        return False
    expected = {"optimal":(0,"resolved"),"empty":(0,"resolved"),"infeasible":(0,"resolved"),"unbounded":(0,"resolved"),
        "verification_failed":(3,"verification_failed"),"time_limit":(4,"incomplete"),"iteration_limit":(4,"incomplete"),"numerical_error":(4,"incomplete")}
    status=r.get("status")
    if not isinstance(status,str) or status not in expected or expected[status] != (row["returncode"],row.get("classification")):
        return False
    nullable={"ipm_kkt_dimension","ipm_factor_nonzeros","ipm_eliminated_singletons"}
    if any(k not in r or not (r[k] is None and k in nullable or integer(r[k])) for k in COUNT_FIELDS):
        return False
    if any(k in r for k in ("ipm_extended_krylov_attempts","ipm_extended_krylov_successes","ipm_homogeneous_scalar_checks","ipm_homogeneous_scalar_rejections")):
        return False
    if r["ipm_weighted_krylov_steps"] or not (r["ipm_homogeneous_constant_repair_successes"] <= r["ipm_homogeneous_constant_repairs"] <= r["ipm_homogeneous_constant_solves"]):
        return False
    timings=r.get("timings")
    if not isinstance(timings,dict) or not all(finite(timings.get(k)) and timings[k]>=0 for k in ("read_seconds","solve_seconds","verification_seconds","total_seconds")):
        return False
    return finite(row.get("numerical_seconds")) and row["numerical_seconds"]>=0 and finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"]>0


def pair_category(left,right):
    if not valid_report(left) or not valid_report(right):
        return "invalid_process"
    if any(x["report"]["status"]=="time_limit" or x["numerical_seconds"]>5 or x["elapsed_wall_seconds"]>35 for x in (left,right)):
        return "budget_limited"
    a,b=({key:value for key,value in row["report"].items() if key!="timings"} for row in (left,right))
    return "equal" if same(a,b) and left["returncode"]==right["returncode"] else "different"


def packed_check(record,value):
    require(isinstance(record,dict) and set(record)=={"numerator","denominator","decimal80","sign"},"精确标量字段")
    require(record["numerator"]==str(value.numerator) and record["denominator"]==str(value.denominator),"精确标量分子分母")
    require(type(record["sign"]) is int and record["sign"]==(value>0)-(value<0),"精确标量符号")
    with localcontext() as context:
        context.prec=80
        require(record["decimal80"]==str(Decimal(value.numerator)/Decimal(value.denominator)),"精确标量十进制")


def vector_check(record,values):
    index=max(range(len(values)),key=lambda i:abs(values[i])) if values else None
    value=values[index] if index is not None else ZERO
    require(record["argmax"]==index,"向量最大坐标")
    packed_check(record["infinity"],abs(value));packed_check(record["signed_at_argmax"],value)


def tolerance(text):
    match=re.fullmatch(r"([+-]?)0[xX]([0-9a-fA-F]+)(?:\.([0-9a-fA-F]*))?[pP]([+-]?\d+)",text)
    require(match is not None,"容差十六进制")
    sign,whole,tail,exponent=match.groups();tail=tail or ""
    significand=int(whole+tail,16)*(-1 if sign=="-" else 1)
    shift=int(exponent)-4*len(tail)
    require(abs(shift)<65536,"容差指数范围")
    return Fraction(significand*(1<<shift)) if shift>=0 else Fraction(significand,1<<-shift)


def powers(exponent):
    return Fraction(1<<exponent) if exponent>=0 else Fraction(1,1<<-exponent)


def exponent_of(value):
    require(value>0,"正数指数")
    exponent=value.numerator.bit_length()-value.denominator.bit_length()
    return exponent-int(value < powers(exponent))


def wide_round(value,precision,minimum,maximum):
    if not value:return ZERO
    sign=-1 if value<0 else 1;value=abs(value)
    step=max(exponent_of(value)+1-precision,minimum-precision)
    quotient=value/powers(step)
    whole,remainder=divmod(quotient.numerator,quotient.denominator)
    whole+=int(2*remainder>quotient.denominator or 2*remainder==quotient.denominator and whole%2==1)
    result=whole*powers(step)
    if result>=powers(maximum):raise OverflowError("浮点舍入溢出")
    return sign*result


def production_point(data,coefficients):
    a=data["arrays"];point=list(a["base"]);d=len(point)
    for j,coefficient in enumerate(coefficients):
        for i in range(d):
            direction=a["z"][j*d+i]
            product=coefficient*direction
            if not math.isfinite(product):raise OverflowError("乘积溢出")
            value=Fraction(point[i])+Fraction(product)
            rounded=wide_round(value,*data["wide"])
            result=float(rounded)
            if not result:
                negative=value<0 or not value and point[i]==0 and product==0 and math.copysign(1,point[i])<0 and math.copysign(1,product)<0
                result=-0.0 if negative else 0.0
            if not math.isfinite(result):raise OverflowError("写回溢出")
            point[i]=result
    return point


def combination(data,coefficients):
    a=data["arrays"];d=data["dimension"]
    return [Fraction(a["base"][i])+sum((coefficient*Fraction(a["z"][j*d+i]) for j,coefficient in enumerate(coefficients)),ZERO) for i in range(d)]


def operator_product(data,point):
    a=data["arrays"];n=data["n"];m=data["m"]
    result=[ZERO for _ in range(n)]+[-Fraction(a["h"][i])*point[n+i] for i in range(m)]
    for col in range(n):
        for k in range(a["g_starts"][col],a["g_starts"][col+1]):
            row=n+a["g_rows"][k];value=Fraction(a["g_values"][k])
            result[col]+=value*point[row];result[row]+=value*point[col]
    return result


def residual(data,point):
    return [Fraction(b)-value for b,value in zip(data["arrays"]["linear_rhs"],operator_product(data,point))]


def residual_check(record,data,values):
    ratios=[abs(value)/allowed for value,allowed in zip(values,data["allowed"])]
    worst=max(range(len(ratios)),key=ratios.__getitem__)
    require(record["satisfies_original_tolerances"] is all(value<=1 for value in ratios),"原方程接受标记")
    require(record["worst_coordinate"]==worst,"残差最坏坐标")
    packed_check(record["maximum_normalized_residual"],ratios[worst]);packed_check(record["signed_residual_at_worst"],values[worst])
    vector_check(record["upper_infinity"],values[:data["n"]]);vector_check(record["lower_infinity"],values[data["n"]:])


def work_check(work):
    for key in ("ir_candidates","ir_corrections_started","ir_corrections_completed","krylov_calls"):
        require(integer(work[key]),"工作计数类型")
    require(work["ir_candidates"]<=3 and work["ir_corrections_completed"]<=work["ir_corrections_started"]<=2 and work["krylov_calls"]<=1,"IR工作范围")
    require(len(work["cycles"])==3,"周期数")
    for i,c in enumerate(work["cycles"]):
        require(type(c["restart_index"]) is int and c["restart_index"]==i,"周期索引")
        require(type(c["started"]) is bool and type(c["ended"]) is bool,"周期开始结束类型")
        for key in ("columns_started","preconditioner_solves_completed","columns_completed","candidates","remaining_zero_count"):
            require(integer(c[key]),"列工作计数类型")
        require(0<=c["candidates"]<=c["columns_completed"]<=c["preconditioner_solves_completed"]<=c["columns_started"]<=32,"列工作顺序")
        require(c["remaining_zero_count"]<=c["columns_completed"] and (c["started"] or not c["ended"] and not c["columns_started"]),"周期未启动或退化账本")


CAPTURE_COUNTS=("completed_iterations","factorizations","refinements","constant_solves","direction_solves","constant_repairs","constant_repair_successes")
REPORT_COUNTS=("ipm_iterations","ipm_factorizations","ipm_refinement_steps","ipm_homogeneous_constant_solves","ipm_homogeneous_direction_solves","ipm_homogeneous_constant_repairs","ipm_homogeneous_constant_repair_successes")


def capture_read(path,plan,row):
    meta=read(path);binary=path.with_suffix(".bin");blob=binary.read_bytes()
    require(type(meta["schema"]) is int and meta["schema"]==1 and meta["run_started"] is True,"捕获schema/启动")
    require(meta["status"] in ("captured","no_target_failure") and meta["truncated"] is False and meta["error"]=="","捕获状态")
    for key in ("capture_errors","capture_started","terminal_failures","event_count","ordinary_scopes_started","ordinary_scopes_completed","ordinary_scopes_unwound","fixed_cache_bytes","binary_bytes"):
        require(integer(meta[key]),"采集计数整数")
    require(meta["capture_errors"]==0 and type(meta["terminal"]) is bool,"采集错误")
    require(meta["ordinary_scopes_started"]==meta["ordinary_scopes_completed"]+meta["ordinary_scopes_unwound"],"scope闭合")
    require(meta["last_scope_exit"] in ("not_started","returned","nonterminal_exception","krylov_exhausted"),"scope退出")
    work_check(meta["last_scope_work"])
    require(all(integer(meta["last_scope_after_counts"][key]) for key in CAPTURE_COUNTS),"scope末计数")
    limits={key:plan[key] for key in ("maximum_events","maximum_columns","cache_limit_bytes","metadata_limit_bytes")}
    require(all(type(meta["limits"][key]) is int for key in limits) and same(meta["limits"],limits),"捕获上限")
    require(meta["byte_order"]=="little" and blob[:8]==b"V67KRY01" and len(blob)==meta["binary_bytes"],"捕获字节头")
    require(path.stat().st_size<=65536 and 0<meta["fixed_cache_bytes"]<=134217728 and len(blob)<=134217736,"捕获大小")
    markers=[line[len("V67_KRYLOV "):] for line in row["stderr"].splitlines() if line.startswith("V67_KRYLOV ")]
    require(len(markers)==1,"唯一采集marker");mark=strict(markers[0])
    require(type(mark["schema"]) is int and mark["schema"]==1 and mark["write_ok"] is True,"marker写出成功")
    require(all(same(mark[key],meta[key]) for key in ("status","event_count","capture_errors","truncated","terminal_failures")),"marker与文件一致")
    require(isinstance(meta["events"],list) and len(meta["events"])==meta["event_count"]<=1,"捕获事件上限")
    if not meta["events"]:
        require(meta["status"]=="no_target_failure" and meta["terminal"] is False and meta["terminal_failures"]==0 and len(blob)==8,"零事件控制")
        return meta,None
    e=meta["events"][0]
    require(meta["status"]=="captured" and meta["terminal"] is True and meta["terminal_failures"]==1 and meta["capture_started"]>=1 and meta["last_scope_exit"]=="krylov_exhausted","真最终耗尽")
    require(type(e["index"]) is int and e["index"]==0 and e["phase"]=="ordinary_constant" and e["linear_exit"]=="krylov_exhausted" and e["terminal"] is True,"事件类型")
    require(e["candidate_submitted"] is False and e["residual_sign"]=="rhs_minus_K0_candidate","未提交及残差符号")
    require(all(e[key] is True for key in ("base_available","z_available","coefficients_available","last_candidate_available","last_residual_available","linear_rhs_available")),"数组完整")
    for key in ("iteration","n","m","dimension","nnz","generated_columns","coefficient_count","payload_bytes","cache_bytes","restart_index","column_index"):
        require(integer(e[key]),"事件整数字段")
    n,m,d,nnz,k,cc=(e[key] for key in ("n","m","dimension","nnz","generated_columns","coefficient_count"))
    require(d==n+m and d>0 and 1<=cc<=k<=32 and e["restart_index"]==2 and e["column_index"]==cc-1,"事件维数")
    require(e["cache_bytes"]==meta["fixed_cache_bytes"]+e["payload_bytes"]<=134217728 and len(blob)==e["payload_bytes"]+8,"事件缓存账本")
    work_check(e["work"])
    require(same(e["work"],meta["last_scope_work"]) and e["work"]["krylov_calls"]==1 and all(c["started"] and c["ended"] for c in e["work"]["cycles"]),"完整3周期")
    require(e["work"]["cycles"][2]["columns_completed"]==k,"实际Z列数")
    require(same(e["after_counts"],meta["last_scope_after_counts"]),"末scope账本一致")
    for key,field in zip(CAPTURE_COUNTS,REPORT_COUNTS):
        require(integer(e["before_counts"][key]) and integer(e["after_counts"][key]) and e["before_counts"][key]<=e["after_counts"][key]<=row["report"][field],"采集/报告计数边界")
    require(e["after_counts"]["refinements"]-e["before_counts"]["refinements"]==e["work"]["ir_corrections_completed"]+sum(c["preconditioner_solves_completed"] for c in e["work"]["cycles"]),"refinement逐项账本")
    specs=(("g_starts","q",[n+1]),("g_rows","q",[nnz]),("g_values","d",[nnz]),("h","d",[m]),("linear_rhs","d",[d]),
        ("base","d",[d]),("z","d",[k,d]),("coefficients","d",[cc]),("last_candidate","d",[d]),("last_residual","d",[d]))
    require(len(e["arrays"])==10,"10个数组")
    cursor=8;arrays={}
    for desc,(name,kind,shape) in zip(e["arrays"],specs):
        length=math.prod(shape)
        require(all(integer(desc[key]) for key in ("count","width","offset")) and all(integer(v) for v in desc["shape"]),"数组描述整数")
        require(same(desc,{"name":name,"dtype":"int64" if kind=="q" else "float64","count":length,"width":8,"offset":cursor,"shape":shape}),"数组连续布局")
        values=array(kind);values.frombytes(blob[cursor:cursor+length*8])
        if sys.byteorder!="little":values.byteswap()
        require(len(values)==length and values.itemsize==8,"实际数组长度")
        if kind=="d":require(all(math.isfinite(x) for x in values),"实际数组有限")
        arrays[name]=values;cursor+=length*8
    require(cursor==len(blob),"二进制无尾部")
    starts,rows=arrays["g_starts"],arrays["g_rows"]
    require(starts[0]==0 and starts[-1]==nnz and all(0<=x<=y<=nnz for x,y in zip(starts,starts[1:])) and all(0<=r<m for r in rows),"CSC边界")
    require(all(rows[j]<rows[j+1] for c in range(n) for j in range(starts[c],starts[c+1]-1)),"CSC列内严格升序")
    require(all(value>=0 for value in arrays["h"]),"实际H非负")
    tol=tolerance(e["global_tolerance"]);blocks=[tolerance(v) for v in e["block_tolerances"]] if e["block_tolerances"] is not None else None
    require(tol>0 and (blocks is None or len(blocks)==2 and min(blocks)>0),"实际容差正数")
    fp=meta["floating_point"];wide=tuple(fp["long_double"][key] for key in ("digits","min_exponent","max_exponent"))
    require(all(type(v) is int for v in wide) and 53<=wide[0]<=113 and wide[1]<=-1021 and wide[2]>=1024,"宽格式")
    require(all(type(fp["double"][key]) is int and fp["double"][key]==value for key,value in (("bytes",8),("digits",53),("min_exponent",-1021),("max_exponent",1024))),"binary64格式")
    require(fp["double"]["is_iec559"] is True and fp["long_double"]["is_iec559"] is True and type(fp["flt_eval_method"]) is int and fp["flt_eval_method"]==0 and meta["rounding_mode"]["is_to_nearest"] is True,"实际表达式舍入")
    digest=hashlib.sha256(blob)
    digest.update(json.dumps({"n":n,"m":m,"k":k,"cc":cc,"global":str(tol),"blocks":[str(v) for v in blocks] if blocks else None,"wide":list(wide)},sort_keys=True).encode())
    return meta,{"arrays":arrays,"n":n,"m":m,"dimension":d,"k":k,"cc":cc,"event":e,"wide":wide,
        "allowed":[min(tol,blocks[int(i>=n)]) if blocks else tol for i in range(d)],"numerical_sha256":digest.hexdigest()}


def model_check(model,data,center_residual):
    """核所有约束与落盘边界；不重复整块精确 K0Z 投影。"""
    path=Path(model["path"])
    require(sha(path)==model["sha256"] and path.stat().st_size==model["bytes"],"oracle模型身份")
    d,k=data["dimension"],data["k"]
    require(model["rows"]==2*d and model["columns"]==k+1 and len(model["column_scale_exponents"])==k,"oracle模型维数")
    require(all(type(x) is int for x in model["column_scale_exponents"]),"变量二次幂尺度")
    lines=iter(path.read_text(encoding="ascii").splitlines())
    def expect(tokens):
        require(next(lines).split()==tokens,"MPS顺序或约束集合")
    expect(["NAME","V67_DIAGNOSTIC"]);expect(["ROWS"]);expect(["N","OBJ"])
    for i in range(d):expect(["L","P"+str(i)]);expect(["L","N"+str(i)])
    expect(["COLUMNS"])
    look=next(lines).split();nonzeros=2*d;small=0;zero_columns=0
    for j in range(k):
        require(look==["X"+str(j),"OBJ","0"],"MPS保留全部生成列")
        previous=-1;peak=0.0;look=next(lines).split()
        while look[0]=="X"+str(j):
            require(len(look)==5 and look[1].startswith("P"),"投影双侧行")
            i=int(look[1][1:]);positive=float(look[2]);negative=float(look[4])
            require(previous<i<d and look[3]=="N"+str(i) and math.isfinite(positive) and positive!=0 and negative==-positive,"双侧系数符号")
            previous=i;peak=max(peak,abs(positive));nonzeros+=2;small+=2*int(abs(positive)<=1e-9)
            look=next(lines).split()
        if not peak:zero_columns+=1
        else:require(1<=peak<=2,"列尺度后峰值应在[1,2]")
    require(look==["T","OBJ","1"],"无穷范数目标变量")
    for i in range(d):expect(["T","P"+str(i),"-1","N"+str(i),"-1"])
    expect(["RHS"])
    for i,value in enumerate(center_residual):
        row=next(lines).split();v=float(value/data["allowed"][i])
        require(len(row)==5 and row[0]=="RHS1" and row[1]=="P"+str(i) and row[3]=="N"+str(i) and float(row[2])==v and float(row[4])==-v,"精确中心RHS转换")
    expect(["BOUNDS"])
    for j in range(k):expect(["FR","BND","X"+str(j)])
    expect(["LO","BND","T","0"]);expect(["ENDATA"])
    require(next(lines,None) is None,"MPS无尾部")
    require(model["rounding"]["written_matrix_nonzeros"]==nonzeros and model["rounding"]["zero_projected_columns"]==zero_columns and model["rounding"]["nonzero_at_or_below_highs_default_small_matrix_value"]==small,"MPS计数")
    for field in ("projection_seconds","model_generation_seconds_including_projection","model_write_and_conversion_seconds"):
        require(finite(model[field]) and model[field]>=0,"建模成本")
    require(math.isclose(model["projection_seconds"]+model["model_write_and_conversion_seconds"],model["model_generation_seconds_including_projection"],rel_tol=1e-12,abs_tol=1e-9),"建模成本分解")


def oracle_check(record,model,plan):
    path=Path(record["report_path"])
    expected=[str(ROOT/".tools/solver-ipm-v66.exe"),"solve",model["path"],"--backend","highs","--highs-solver","simplex",
        "--highs-presolve","choose","--threads","1","--seed","0","--time-limit","60","--output",str(path)]
    require(record["command"]==expected and record["cwd"]==str(ROOT),"离线oracle命令")
    require(record["oracle_sha256"]==plan["parent_solver_sha256"] and record["wall_timeout_seconds"]==90 and record["numerical_time_limit_seconds"]==60,"oracle身份预算")
    require(finite(record["wall_seconds"]) and record["wall_seconds"]>=0 and record["started_at_utc"]<=record["completed_at_utc"],"oracle时间账本")
    require(type(record["returncode"]) is int and type(record["wall_timeout"]) is bool,"oracle退出及超时类型")
    for kind in ("stdout","stderr"):
        require(sha(record[kind+"_path"])==record[kind+"_sha256"],"oracle原始输出身份")
    require(same(read(path.parent/"oracle-process.json"),record),"oracle调用账本落盘")
    if record["report_sha256"] is None:
        require(not path.exists(),"没有报告时无伪造身份")
        return None
    require(sha(path)==record["report_sha256"],"oracle报告身份")
    report=read(path)
    require(report["backend"]=="highs" and record["status"]==report["status"],"oracle报告后端状态")
    require(same(strict(Path(record["stdout_path"]).read_text(encoding="utf-8")),report),"oracle标准输出与落盘报告一致")
    require(report["input"]==model["path"] and report["backend_version"]=="1.15.1","oracle输入及版本")
    require(same(record["reported_timings"],report["timings"]),"oracle原timings")
    for key in ("read_seconds","solve_seconds","verification_seconds"):
        require(finite(report["timings"][key]) and report["timings"][key]>=0,"oracle报告成本有限")
    seconds=report["timings"]["solve_seconds"]+report["timings"]["verification_seconds"]
    require(record["reported_numerical_seconds"]==seconds and record["reported_numerical_budget_exceeded"] is (seconds>60),"oracle数值预算单列")
    if report["status"]=="error":
        require(record["returncode"]==2 and record["wall_timeout"] is False and report["has_solution"] is False and report["solution"] is None,"oracle失败退出无候选")
        require(report["message"]=="模型读取产生警告，已拒绝求解以避免静默修改或丢失模型语义" and seconds==0,"本轮oracle读取警告在求解前拒绝")
    return report


def analyze_check(result,data,plan):
    require(result["numerical_sha256"]==data["numerical_sha256"] and result["dimension"]==data["dimension"],"分析输入身份")
    require(result["event"]=={key:data["event"][key] for key in ("phase","iteration","restart_index","column_index","generated_columns","coefficient_count")},"分析事件标识")
    a=data["arrays"];replayed=production_point(data,a["coefficients"])
    mismatch=[i for i,(x,y) in enumerate(zip(replayed,a["last_candidate"])) if struct.pack("<d",x)!=struct.pack("<d",y)]
    replay=result["production_replay"]
    require(replay["bitwise_equal"] is (not mismatch) and replay["mismatch_count"]==len(mismatch) and replay["first_mismatches"]==mismatch[:8],"实际候选逐项舍入重放")
    require(finite(replay["seconds"]) and replay["seconds"]>=0,"重放成本")
    if mismatch:
        require(result["classification"]=="production_replay_mismatch_no_oracle" and result["oracle_runs"]==0,"不匹配禁止oracle推断")
        return {"witness":False,"oracle_runs":0,"replay_equal":False}
    a0=[Fraction(v) for v in a["coefficients"]]+[ZERO]*(data["k"]-data["cc"])
    baseline=result["baseline"]
    require(len(baseline["coefficients"])==len(a0),"原系数维数")
    for packed,value in zip(baseline["coefficients"],a0):packed_check(packed,value)
    center=residual(data,combination(data,a0));original=residual(data,[Fraction(v) for v in a["last_candidate"]])
    residual_check(baseline["exact_continuous"],data,center)
    residual_check(baseline["production_candidate_exact"],data,original)
    stored=[Fraction(v) for v in a["last_residual"]]
    residual_check(baseline["production_stored_residual"],data,stored)
    vector_check(baseline["stored_residual_evaluation_error"],[x-y for x,y in zip(stored,original)])
    require(finite(baseline["exact_center_and_baseline_seconds"]) and baseline["exact_center_and_baseline_seconds"]>=0,"原点复核成本")
    baseline_outcome={
        "continuous_baseline_witness":all(abs(value)<=allowed for value,allowed in zip(center,data["allowed"])),
        "production_baseline_witness":all(abs(value)<=allowed for value,allowed in zip(original,data["allowed"])),
        "production_stored_accepted":all(abs(value)<=allowed for value,allowed in zip(stored,data["allowed"])),
        "continuous_baseline_maximum_normalized_residual":baseline["exact_continuous"]["maximum_normalized_residual"]["decimal80"],
        "production_baseline_maximum_normalized_residual":baseline["production_candidate_exact"]["maximum_normalized_residual"]["decimal80"]}
    model_check(result["diagnostic_model"],data,center)
    require(result["oracle_runs"]==1,"每唯一捕获最多一次oracle")
    report=oracle_check(result["oracle"],result["diagnostic_model"],plan)
    solution=report.get("solution") if isinstance(report,dict) else None
    if not isinstance(solution,list) or len(solution)!=data["k"]+1 or not all(finite(v) for v in solution):
        require(result["classification"]=="no_finite_oracle_candidate","无有限见证不宣布空间无解")
        require(not any(key in result for key in ("oracle_solution","oracle_map_continuous","double_coefficients_continuous","production_combination_exact","production_candidate_sha256")),"无oracle候选时不伪造映射见证")
        return {"witness":False,"oracle_runs":1,"replay_equal":True,"oracle_candidate_available":False,
            "oracle_status":result["oracle"]["status"],"oracle_returncode":result["oracle"]["returncode"],
            "oracle_solve_seconds":report["timings"]["solve_seconds"] if report else None,**baseline_outcome}
    exact=[v+powers(e)*Fraction(float(delta)) for v,e,delta in zip(a0,result["diagnostic_model"]["column_scale_exponents"],solution[:-1])]
    oracle_solution=result["oracle_solution"]
    require(oracle_solution["delta_binary64_hex"]==[float(x).hex() for x in solution[:-1]] and oracle_solution["reported_t"]==solution[-1],"oracle原解映射")
    require(len(oracle_solution["a_exact"])==len(exact),"精确映射系数数目")
    for packed,value in zip(oracle_solution["a_exact"],exact):packed_check(packed,value)
    residual_check(result["oracle_map_continuous"],data,residual(data,combination(data,exact)))
    try:
        coefficients=[float(v) for v in exact]
        if not all(math.isfinite(v) for v in coefficients):raise OverflowError("系数不可表示")
        require(oracle_solution["a_double_hex"]==[x.hex() for x in coefficients],"映射binary64系数")
        residual_check(result["double_coefficients_continuous"],data,residual(data,combination(data,[Fraction(v) for v in coefficients])))
        point=production_point(data,coefficients)
        final=residual(data,[Fraction(v) for v in point]);residual_check(result["production_combination_exact"],data,final)
        require(result["production_candidate_sha256"]==hashlib.sha256(b"".join(struct.pack("<d",v) for v in point)).hexdigest(),"见证点逐字身份")
        witness=all(abs(v)<=allowed for v,allowed in zip(final,data["allowed"]))
        require(result["classification"]==("production_point_exact_witness_found" if witness else "oracle_candidate_does_not_provide_production_witness"),"仅按原残差判见证")
    except OverflowError:
        require(result["classification"]=="oracle_coefficients_not_representable_in_production","溢出不虚称见证");witness=False
    require(finite(result["witness_verification_seconds"]) and result["witness_verification_seconds"]>=0,"见证复核成本")
    return {"witness":witness,"oracle_runs":1,"replay_equal":True,"oracle_candidate_available":True,**baseline_outcome}


def attempts_check():
    required=("runner-self-check","build-self-check","build","run","analyzer-self-check","analysis")
    result={}
    for label in required:
        paths=sorted(DATA.glob("v67-"+label+"-attempt*.json"))
        require(bool(paths),"缺少实际执行记录："+label)
        success=[]
        for path in paths:
            record=read(path)
            require(hashlib.sha256(record["source"].encode("utf-8")).hexdigest()==record["source_sha256"],"attempt原源码字节身份")
            require(hashlib.sha256(record["wrapper_source"].encode("utf-8")).hexdigest()==record["wrapper_sha256"],"attempt包装器身份")
            require(record["started_at_utc"]<=record["completed_at_utc"] and finite(record["elapsed_seconds"]) and record["elapsed_seconds"]>=0,"真实开始完成时间")
