        require(result[left]["completed_at_utc"]<=result[right]["started_at_utc"],"阶段真实串行顺序")
    selfcheck=read(DATA/"v67-runner-self-check.json")
    require(same(selfcheck,strict(result["runner-self-check"]["stdout"])),"纯自检实际输出物化")
    require(selfcheck=={"passed":True,"trajectory_checks":18,"typed_checks":2,"count_checks":289,
        "all_status_invalid_budget_checks":320,"capture_checks":49,"commands_checked":6,"schedule_rows":18,"lp_runs":0,"filesystem_hashes":0},"runner自检覆盖")
    return result


def identity_check(plan):
    checked={}
    def identity(path,expected):
        path=Path(path).resolve();key=str(path)
        if key not in checked:checked[key]=sha(path)
        require(checked[key]==expected,"文件身份："+key)
    for filename,expected in (("v67-plan.json",PLAN_SHA),("ipm-v66-identity.json",plan["parent_identity_sha256"]),
        (plan["baseline_identity_file"],plan["baseline_identity_sha256"]),(plan["baseline_verification_file"],plan["baseline_verification_sha256"]),
        (plan["evidence_file"],plan["evidence_sha256"]),("ipm-v66-source.zip",plan["parent_source_sha256"])):
        identity(DATA/filename,expected)
    parent=read(DATA/"ipm-v66-identity.json");baseline=read(DATA/plan["baseline_identity_file"])
    build=read(WORK/"build-manifest.json");manifest=read(DATA/"v67-run-manifest.json")
    require(parent["files"]==baseline["files"]==build["frozen_files"]==build["current_files"] and len(parent["files"])==95,"95来源同父版")
    require(parent["libraries"]==baseline["libraries"]==build["actual_libraries"] and len(parent["libraries"])==17,"17库同父版")
    require(sum("libsolver_" not in Path(path).name for path in parent["libraries"])==8,"8第三方库")
    for group in (parent["files"],parent["libraries"]):
        for name,expected in group.items():identity(ROOT/name,expected)
    for name,expected in parent["files"].items():identity(WORK/"frozen"/name,expected)
    with zipfile.ZipFile(DATA/"ipm-v66-source.zip") as archive:
        require(len(archive.namelist())==95 and set(archive.namelist())==set(parent["files"]),"父版源码zip恰95项")
        for name,expected in parent["files"].items():require(hashlib.sha256(archive.read(name)).hexdigest()==expected,"zip逐项身份")
    for key in ("plan_sha256","baseline_identity_sha256","parent_identity_sha256"):
        require(build[key]==(PLAN_SHA if key=="plan_sha256" else plan[key]),"构建计划身份")
    require(build["production_sha256"]==baseline["solver_sha256"]==plan["parent_solver_sha256"]==build["frozen_parent_sha256"],"生产/冻结程序同父版")
    for path,key in (("build/release/solver.exe","production_sha256"),(".tools/solver-ipm-v66.exe","frozen_parent_sha256"),(".tools/v67-diagnostic/solver-diagnostic.exe","executable_sha256")):
        identity(ROOT/path,build[key])
    for key in ("protected_before_and_after","link_explicit_before_and_after","compile_inputs_after_and_final","outputs"):
        for path,expected in build[key].items():identity(path,expected)
    require(manifest["plan_sha256"]==PLAN_SHA and manifest["environment"]=={"OMP_NUM_THREADS":"1","OPENBLAS_NUM_THREADS":"1","MKL_NUM_THREADS":"1"},"运行环境冻结")
    for path,expected in manifest["protected"].items():identity(path,expected)
    tree=ast.parse((DATA/"v67-krylov-instrumentation.py").read_text(encoding="utf-8"))
    changes=next(node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name=="changes")
    anchors=ast.literal_eval(next(node for node in changes.body if isinstance(node,ast.Return)).value)
    require(len(anchors)==14,"固定14插桩锚点")
    original=(WORK/"frozen/src/ipm.cpp").read_text(encoding="utf-8");patched=(WORK/"ipm-diagnostic.cpp").read_text(encoding="utf-8")
    restored=patched
    for anchor,before,after in reversed(anchors):
        replacement=before+anchor+after
        require(restored.count(replacement)==1,"逆插桩唯一")
        restored=restored.replace(replacement,anchor,1)
    require(restored==original,"插桩逐字逆变换")
    static=read(WORK/"static-check.json")
    require(static["passed"] is True and static["anchor_count"]==14 and static["reversible"] is True and static["solver_runs"]==0,"插桩自检证据")
    require(static["original_normalized_sha256"]==hashlib.sha256(original.encode()).hexdigest() and static["transformed_sha256"]==hashlib.sha256(patched.encode()).hexdigest(),"插桩规范化字节")
    commands=build["commands"]
    require(set(commands["compile"])==set(commands["original_compile"])=={"ipm","main","highs","pdlp"},"四个ABI一致编译单元")
    for unit in commands["compile"]:
        command=commands["compile"][unit];record=read(WORK/(unit+"-compile.json"))
        require(command==record["command"] and record["returncode"]==0 and record["wall_timeout"] is False,"真实编译完成")
        require(command[0]==commands["original_compile"][unit][0] and "-O3" in command and "-std=c++20" in command and "-DNDEBUG" in command,"相同编译器与优化ABI")
        source=Path(command[command.index("-c")+1])
        require(source==(WORK/"ipm-diagnostic.cpp" if unit=="ipm" else WORK/"frozen/src"/{"main":"main.cpp","highs":"highs_backend.cpp","pdlp":"pdlp.cpp"}[unit]),"编译源来自冻结目录")
    linked=read(WORK/"link.json")
    require(linked["returncode"]==0 and linked["command"]==commands["link"] and linked["wall_timeout"] is False,"实际链接完成")
    capture_tests=read(WORK/"capture-self-check.json")
    require(capture_tests["passed"] is True and capture_tests["off_on_pairs"]==8 and capture_tests["lp_runs"]==0,"8对采集器自检")
    cases=("captured","no_trigger","nonterminal","prepared_nonterminal","cache_limit","short_cycle","missing_candidate","event_limit")
    require([r["case"] for r in capture_tests["cases"]]==list(cases),"采集器自检集合")
    for case in cases:
        off=read(WORK/("krylov-self-"+case+"-off-run.json"));on=read(WORK/("krylov-self-"+case+"-on-run.json"))
        require(off["returncode"]==on["returncode"]==0 and off["stdout"]==on["stdout"] and off["stderr"]=="","采集器开关输出一致")
        require(strict(on["stdout"])["passed"] is True,"采集器真实自检输出")
        metadata=read(WORK/("krylov-self-"+case+"-on.json"))
        event=case in ("captured","short_cycle","event_limit");error=case in ("cache_limit","missing_candidate")
        require(metadata["event_count"]==int(event) and metadata["capture_errors"]==int(error) and metadata["truncated"] is (case=="cache_limit"),"采集器正负控制结果")
    return build,checked


def rows_check(plan,build):
    raw=DATA/"v67-runs.jsonl.gz";summary=read(DATA/"v67-summary.json")
    rows=[strict(line) for line in gzip.decompress(raw.read_bytes()).splitlines()]
    require(plan["variants"]==list(VARIANTS) and plan["repeats"]==2 and plan["runs"]==18 and len(rows)==18,"18固定运行")
    require([m["name"] for m in plan["models"]]==["greenbea","forplan","greenbeb"],"固定模型顺序")
    bycase={};captures=[];pair_results=[]
    sys.path.insert(0,str(ROOT/"scripts"))
    import benchmark,compare_lp
    index=0
    for mi,model in enumerate(plan["models"]):
        require(sha(model["input"])==model["sha256"],"输入模型身份")
        for repetition in range(2):
            case=2*mi+repetition;selected={};order=VARIANTS[case%3:]+VARIANTS[:case%3]
            for variant in order:
                row=rows[index];index+=1
                require((row["index"],row["case_index"],row["model_index"],row["repetition"],row["variant"],row["model"],row["input"])
                    ==(index-1,case,mi,repetition,variant,model["name"],model["input"]),"实际串行轮转顺序")
                exe=build["frozen_parent_executable"] if variant=="frozen_v66" else build["executable"]
                digest=build["frozen_parent_sha256"] if variant=="frozen_v66" else build["executable_sha256"]
                require(row["command"][:3]==[exe,"solve",model["input"]],"实际执行文件与输入")
                expected={"--backend":"ipm","--time-limit":"5","--threads":"1","--seed":"0","--mip-gap":"0.0001","--iteration-limit":"200","--scaling-passes":"5",
                    "--ipm-method":"homogeneous","--ipm-linear-accuracy":"homogeneous_repair","--ipm-linear-solver":"normal_cholmod_aat","--ipm-objective-scaling":"off","--ipm-direction-retries":"0",
                    **{"--ipm-"+k:v for k,v in plan["shared_ipm"].items()}}
                require(flags(row["command"][3:])==expected,"完整CLI参数")
                r=strict(row["stdout"]);require(same(r,row["report"]),"原始stdout完整报告")
                require(row["configuration_matches"] is True and r["input"]==model["input"] and same(r["options"],plan["expected_report_options"]),"报告完整options")
                require(row["hashes_before"]==row["hashes_after"]=={"input":model["sha256"],"solver":digest},"进程前后模型程序身份")
                require(valid_report(row) and benchmark.classify(row["returncode"],r)==row["classification"],"报告/进程/计数合法")
                require(r["ipm_factor_backend"] is None or r["ipm_factor_backend"]=="normal_cholmod_aat" and r["ipm_structural_fallbacks"]==0 or r["ipm_factor_backend"]=="factorhighs" and r["ipm_structural_fallbacks"]>0,"实际因子标签和fallback")
                require(row["numerical_seconds"]==r["timings"]["solve_seconds"]+r["timings"]["verification_seconds"],"数值耗时重算")
                require(row["quality_failure"]==compare_lp.quality_failure(row,model,model["sha256"],digest,digest),"原模型质量结论")
                require(row["quality_pass"] is (row["quality_failure"] is None),"质量标记")
                prefix=WORK/"captures"/(str(case)+"-"+variant)
                require(row["capture_prefix"]==str(prefix) and row["capture_error"] is None,"采集前缀和完整性")
                if variant!="diagnostic_on":
                    require(row["capture_files"]=={} and row["capture_summary"] is None and not list(prefix.parent.glob(prefix.name+".*")) and "V67_KRYLOV " not in row["stderr"],"关闭采集无输出")
                else:
                    paths=[prefix.with_suffix(".json"),prefix.with_suffix(".bin")]
                    require(set(row["capture_files"])==set(map(str,paths)),"on恰两个捕获文件")
                    for path in paths:require(row["capture_files"][str(path)]=={"sha256":sha(path),"bytes":path.stat().st_size},"捕获落盘身份")
                    meta,data=capture_read(paths[0],plan,row)
                    require(same(row["capture_summary"],{key:meta[key] for key in row["capture_summary"]}),"捕获摘要来自完整元数据")
                    captures.append((row,meta,data,paths[0]))
                selected[variant]=row
            for left,right in zip(VARIANTS,VARIANTS[1:]):
                category=pair_category(selected[left],selected[right]);require(category=="equal","完整非预算对子一致")
                pair_results.append({"case_index":case,"model":model["name"],"repetition":repetition,"left":left,"right":right,
                    "equal":True,"budget_limited":False,"valid_processes":True,"category":category})
            bycase[case]=selected
    require(same(summary["pairs"],pair_results) and summary["raw_sha256"]==sha(raw),"summary完整对子和raw身份")
    require(summary["runs"]==18 and summary["non_budget_pairs"]==summary["non_budget_equal"]==12 and summary["budget_pairs"]==summary["invalid_pairs"]==summary["different_pairs"]==summary["capture_errors"]==0 and summary["diagnostic_trajectory_verified"] is True,"summary各类计数")
    require(len(summary["cases"])==6,"summary六组捕获")
    for case,c in enumerate(summary["cases"]):
        selected=bycase[case];on=selected["diagnostic_on"]
        require(c["case_index"]==case and c["status"]=={v:r["report"]["status"] for v,r in selected.items()},"case状态摘要")
        require(all(same(c[key],on[key]) for key in ("capture_files","capture_prefix","capture_summary")),"case捕获身份摘要")
    for mi in range(3):
        group=[item for item in captures if item[0]["model_index"]==mi]
        require(len(group)==2 and group[0][3].read_bytes()==group[1][3].read_bytes() and group[0][3].with_suffix(".bin").read_bytes()==group[1][3].with_suffix(".bin").read_bytes(),"两次重复捕获逐字一致")
    return captures


def verify(analysis_path,output):
    require(not output.exists(),"不得覆盖正式核验")
    plan=read(DATA/"v67-plan.json")
    records=attempts_check();build,checked=identity_check(plan);captures=rows_check(plan,build)
    require(sha(analysis_path)==ANALYSIS_SHA and sha(DATA/"v67-analyze.py")==ANALYZER_SHA,"实际完成的分析及分析器冻结身份")
    analysis=read(analysis_path)
    require(analysis["schema"]==1 and analysis["completed"] is True and analysis["original_lp_runs"]==0 and analysis["plan_sha256"]==PLAN_SHA,"离线分析完成且无原LP运行")
    require(analysis["analyzer_sha256"]==sha(DATA/"v67-analyze.py") and analysis["exact_helper_sha256"]==sha(DATA/"v53-analyze-hsd.py") and analysis["oracle_sha256"]==plan["parent_solver_sha256"],"分析来源身份")
    require(analysis["oracle_runs"]==len(analysis["oracle_calls"])<=2 and len(analysis["captures"])==6,"oracle总预算及六捕获")
    require(analysis["started_at_utc"]<=analysis["completed_at_utc"] and finite(analysis["elapsed_wall_seconds"]) and analysis["elapsed_wall_seconds"]>=0 and finite(analysis["preflight_seconds"]) and analysis["preflight_seconds"]>=0,"分析成本")
    unique={};outcomes=[]
    for (row,meta,data,path),entry in zip(captures,analysis["captures"]):
        identity={"metadata":str(path),"metadata_sha256":sha(path),"binary":str(path.with_suffix(".bin")),"binary_sha256":sha(path.with_suffix(".bin")),"status":meta["status"]}
        require(all(entry[key]==value for key,value in identity.items()),"分析六输入身份")
        if data is None:
            require(entry["analysis_index"] is None and entry["reason"]=="no_target_failure","零事件不跑oracle")
            continue
        digest=data["numerical_sha256"]
        if digest in unique:
            require(entry["analysis_index"]==unique[digest] and entry["reused_identical_numerical_capture"] is True,"重复数值捕获复用")
        else:
            index=len(unique);unique[digest]=index
            require(entry["analysis_index"]==index and entry["reused_identical_numerical_capture"] is False,"唯一捕获一次分析")
            result=analysis["analyses"][index]
            require(same(result["capture"],identity),"唯一分析完整输入身份")
            outcomes.append(analyze_check(result,data,plan))
    require(len(unique)==analysis["unique_numerical_captures"]==len(analysis["analyses"]),"唯一数值捕获计数")
    require(analysis["oracle_calls"]==[item["oracle"] for item in analysis["analyses"] if item["oracle_runs"]],"oracle预先入账与结果一致")
    require(sum(item["oracle_runs"] for item in outcomes)==analysis["oracle_runs"],"oracle次数不遗漏失败")
    require(records["analysis"]["started_at_utc"]<=analysis["started_at_utc"]<=analysis["completed_at_utc"]<=records["analysis"]["completed_at_utc"],"分析内部外部时间边界")
    result={"passed":True,"created_at_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"plan_sha256":PLAN_SHA,
        "analysis_sha256":sha(analysis_path),"source_sha256":sha(__file__),"checks":CHECKS,"identity_files_checked":len(checked),
        "source_count":95,"library_count":17,"external_library_count":8,"runs":18,"non_budget_equal_pairs":12,
        "capture_files":12,"unique_numerical_captures":len(unique),"oracle_runs_preserved":analysis["oracle_runs"],"analysis_outcomes":outcomes,
        "solver_runs_by_verifier":0,"oracle_runs_by_verifier":0,
        "limits":["独立复核原系数重放与原K0残差；不调用runner判定或分析数学实现。",
            "逐行核MPS全约束和中心RHS，不重复整块精确K0Z投影及其逐项写模误差统计。",
            "只核本轮诊断证据，不新增公开LP性能成绩；离线oracle失败保留，不作不可行证明。"]}
    with output.open("x",encoding="utf-8") as target:json.dump(result,target,ensure_ascii=False,indent=2,allow_nan=False);target.write("\n")
    print(json.dumps(result,ensure_ascii=False))


def self_check():
    report={"schema_version":1,"backend":"ipm","backend_version":"ipm-cpu-0.53.0","status":"numerical_error",**dict.fromkeys(COUNT_FIELDS,0),
        "timings":{"read_seconds":0,"solve_seconds":1,"verification_seconds":0,"total_seconds":1}}
    row={"report":report,"returncode":4,"classification":"incomplete","error":None,"numerical_seconds":1,"elapsed_wall_seconds":2}
    require(valid_report(row) and pair_category(row,row)=="equal","合成正常报告")
    budget=copy.deepcopy(row);budget["report"]["status"]="time_limit"
    require(pair_category(row,budget)=="budget_limited","合成合法预算")
    count_cases=0
    for status,code,classification in (("optimal",0,"resolved"),("empty",0,"resolved"),("infeasible",0,"resolved"),("unbounded",0,"resolved"),
        ("verification_failed",3,"verification_failed"),("time_limit",4,"incomplete"),("iteration_limit",4,"incomplete"),("numerical_error",4,"incomplete")):
        positive=copy.deepcopy(row);positive["report"]["status"]=status;positive.update(returncode=code,classification=classification)
        require(valid_report(positive),"各状态正例")
        for field in COUNT_FIELDS:
            for value in (True,-1,1.0,1<<63):
                bad=copy.deepcopy(positive);bad["report"][field]=value
                require(pair_category(bad,budget)=="invalid_process","坏账本优先于预算");count_cases+=1
    for value in (False,0,-1073741819):
        bad=copy.deepcopy(row);bad["returncode"]=value
        require(pair_category(bad,budget)=="invalid_process","非法退出优先")
    change=copy.deepcopy(row);change["report"]["timings"]["solve_seconds"]=2
    require(pair_category(row,change)=="equal","仅排timings")
    change=copy.deepcopy(row);change["report"]["backend_version"]="ipm-cpu-0.54.0"
    require(pair_category(row,change)=="invalid_process","保留冻结版本")
    require(not same(True,1),"布尔不等于计数")
    require(wide_round(Fraction(1)+powers(-53),53,-1021,1024)==1,"binary64平局偶数")
    require(wide_round(Fraction(1)+3*powers(-53),53,-1021,1024)==1+powers(-51),"binary64奇尾平局")
    require(wide_round(powers(-1075),53,-1021,1024)==0 and wide_round(-3*powers(-1075),53,-1021,1024)==-powers(-1073),"次正规平局")
    require(tolerance("-0x1.8p-2")==Fraction(-3,8),"独立hex解析")
    d={"n":1,"m":1,"dimension":2,"k":1,"cc":1,"wide":(64,-16381,16384),"allowed":[Fraction(1),Fraction(1)],
        "arrays":{"g_starts":[0,1],"g_rows":[0],"g_values":[2.0],"h":[3.0],"linear_rhs":[4.0,-1.0],"base":[0.0,0.0],"z":[1.0,2.0]}}
    require(operator_product(d,[Fraction(1),Fraction(2)])==[Fraction(4),Fraction(-4)],"独立K0两块符号")
    require(residual(d,[Fraction(1),Fraction(2)])==[ZERO,Fraction(3)],"独立原残差")
    require(combination(d,[Fraction(1)])==[Fraction(1),Fraction(2)] and production_point(d,[1.0])==[1.0,2.0],"连续与生产组合")
    print(json.dumps({"passed":True,"checks":CHECKS,"all_status_invalid_budget_checks":count_cases,"solver_runs":0,"oracle_runs":0,"filesystem_hashes":0}))


